{
  "name": "ACQ1102高速数据采集系统",
  "name_en": "ACQ1102 high-speed data acquisition system",
  "manufacturer": "D-TACQ",
  "description": "ACQ1102是一类面向实验室测量与控制的高速数据采集设备，可用于多通道瞬态信号采集、连续数据流监测、触发前后波形记录以及同步时钟/触发路由。结合校准、分段采集、数字输出和波形/脉冲序列加载功能，它适合物理实验、脉冲功率、装置联调和其他需要精确定时的数据记录场景。",
  "description_en": "The ACQ1102 is a high-speed laboratory data acquisition instrument for multi-channel transient capture, live data streaming, pre/post-trigger waveform recording, and synchronized clock/trigger routing. With calibration handling, segmented acquisition, digital outputs, and waveform or pulse-sequence loading, it is suited to physics experiments, pulsed-power setups, system integration, and other precisely timed measurement tasks.",
  "tag_hints": [
    "high-speed data acquisition",
    "transient recording",
    "synchronized triggering",
    "clock routing",
    "segmented acquisition",
    "channel calibration",
    "arbitrary waveform generation",
    "digital I/O pattern generation"
  ],
  "actions": [
    {
      "action_name": "read",
      "description": "读取采集数据。",
      "description_en": "Read acquired data."
    },
    {
      "action_name": "get_blocks",
      "description": "获取数据块。",
      "description_en": "Get data blocks."
    },
    {
      "action_name": "st_monitor",
      "description": "监视状态通道。",
      "description_en": "Monitor the status channel."
    },
    {
      "action_name": "get_state",
      "description": "获取采集状态。",
      "description_en": "Get the acquisition state."
    },
    {
      "action_name": "get_pre",
      "description": "获取触发前样本数。",
      "description_en": "Get the number of pre-trigger samples."
    },
    {
      "action_name": "get_post",
      "description": "获取触发后样本数。",
      "description_en": "Get the number of post-trigger samples."
    },
    {
      "action_name": "get_total",
      "description": "获取总样本数。",
      "description_en": "Get the total sample count."
    },
    {
      "action_name": "get_elapsed",
      "description": "获取已采集样本数。",
      "description_en": "Get the elapsed sample count."
    },
    {
      "action_name": "wait_event",
      "description": "等待设备事件。",
      "description_en": "Wait for a device event."
    },
    {
      "action_name": "wait_armed",
      "description": "等待设备进入布防状态。",
      "description_en": "Wait until the device is armed."
    },
    {
      "action_name": "wait_stopped",
      "description": "等待设备停止。",
      "description_en": "Wait until the device stops."
    },
    {
      "action_name": "wait_state_changed",
      "description": "等待采集状态变化。",
      "description_en": "Wait for the acquisition state to change."
    },
    {
      "action_name": "init_site_client",
      "description": "初始化站点模块访问。",
      "description_en": "Initialize access to a site module."
    },
    {
      "action_name": "make_sa_sd_aliases",
      "description": "建立SA/SD别名。",
      "description_en": "Create SA/SD aliases."
    },
    {
      "action_name": "get_sys_info",
      "description": "获取系统信息。",
      "description_en": "Get system information."
    },
    {
      "action_name": "close",
      "description": "关闭与设备的连接。",
      "description_en": "Close the connection to the device."
    },
    {
      "action_name": "state",
      "description": "获取采集状态。",
      "description_en": "Get the acquisition state."
    },
    {
      "action_name": "post_samples",
      "description": "获取触发后样本数。",
      "description_en": "Get the number of post-trigger samples."
    },
    {
      "action_name": "pre_samples",
      "description": "获取触发前样本数。",
      "description_en": "Get the number of pre-trigger samples."
    },
    {
      "action_name": "elapsed_samples",
      "description": "获取已采集样本数。",
      "description_en": "Get the elapsed sample count."
    },
    {
      "action_name": "demux_status",
      "description": "获取解复用状态。",
      "description_en": "Get the demultiplexing status."
    },
    {
      "action_name": "samples",
      "description": "获取总样本数。",
      "description_en": "Get the total sample count."
    },
    {
      "action_name": "get_aggregator_sites",
      "description": "获取聚合器站点列表。",
      "description_en": "Get the aggregator site list."
    },
    {
      "action_name": "get_aggregator_svc_list",
      "description": "获取聚合服务列表。",
      "description_en": "Get the aggregator service list."
    },
    {
      "action_name": "fetch_all_calibration",
      "description": "获取全部校准数据。",
      "description_en": "Fetch all calibration data."
    },
    {
      "action_name": "scale_raw",
      "description": "按校准参数缩放原始数据。",
      "description_en": "Scale raw data using calibration."
    },
    {
      "action_name": "chan2volts",
      "description": "将通道数据转换为电压值。",
      "description_en": "Convert channel data to volts."
    },
    {
      "action_name": "read_chan",
      "description": "读取单通道采集数据。",
      "description_en": "Read acquired data from one channel."
    },
    {
      "action_name": "read_decims",
      "description": "读取抽取后的数据。",
      "description_en": "Read decimated data."
    },
    {
      "action_name": "nchan",
      "description": "获取通道数量。",
      "description_en": "Get the number of channels."
    },
    {
      "action_name": "data_size",
      "description": "获取数据大小。",
      "description_en": "Get the data size."
    },
    {
      "action_name": "uut_demux_enabled",
      "description": "获取是否启用设备端解复用。",
      "description_en": "Get whether on-device demultiplexing is enabled."
    },
    {
      "action_name": "read_transient_timebase",
      "description": "读取瞬态采集时间基准。",
      "description_en": "Read the transient acquisition timebase."
    },
    {
      "action_name": "load_segments",
      "description": "加载分段采集配置。",
      "description_en": "Load segmented acquisition settings."
    },
    {
      "action_name": "show_segments",
      "description": "显示分段采集配置。",
      "description_en": "Show segmented acquisition settings."
    },
    {
      "action_name": "clear_counters",
      "description": "清除计数器。",
      "description_en": "Clear counters."
    },
    {
      "action_name": "set_sync_routing_master",
      "description": "设置主设备同步路由。",
      "description_en": "Set synchronization routing for master mode."
    },
    {
      "action_name": "set_sync_routing_slave",
      "description": "设置从设备同步路由。",
      "description_en": "Set synchronization routing for slave mode."
    },
    {
      "action_name": "set_sync_routing",
      "description": "设置同步路由。",
      "description_en": "Set synchronization routing."
    },
    {
      "action_name": "set_mb_clk",
      "description": "设置主板时钟。",
      "description_en": "Set the mainboard clock."
    },
    {
      "action_name": "load_stl",
      "description": "加载STL序列。",
      "description_en": "Load an STL sequence."
    },
    {
      "action_name": "load_gpg",
      "description": "加载通用脉冲/模式发生序列。",
      "description_en": "Load a general-purpose pulse/pattern generator sequence."
    },
    {
      "action_name": "load_dpg",
      "description": "加载数字脉冲发生序列。",
      "description_en": "Load a digital pulse generator sequence."
    },
    {
      "action_name": "load_wrpg",
      "description": "加载WRPG序列。",
      "description_en": "Load a WRPG sequence."
    },
    {
      "action_name": "load_dio482pg",
      "description": "加载DIO482脉冲发生序列。",
      "description_en": "Load a DIO482 pulse-generator sequence."
    },
    {
      "action_name": "set_DO",
      "description": "设置数字输出。",
      "description_en": "Set digital outputs."
    },
    {
      "action_name": "load_awg",
      "description": "加载任意波形。",
      "description_en": "Load an arbitrary waveform."
    },
    {
      "action_name": "set_segment",
      "description": "定义单个采集分段。",
      "description_en": "Define a single acquisition segment."
    },
    {
      "action_name": "run_service",
      "description": "运行设备服务。",
      "description_en": "Run a device service."
    }
  ]
}

